1	import { db } from "../lib/db";
2	import { pve, node, waitForTask, nextVmid, pveFor, vmStatus } from "../lib/proxmox";
3	import { writeFile, unlink } from "node:fs/promises";
4	import { ovhConfigured } from "../lib/ovh";
5	import { allocateDedicatedIp, releaseDedicatedIp, syncDedicatedIpPool } from "../lib/dedicated-ip";
6	import { allocateIp, allocateSshPort, gatewayIp } from "../lib/ipam";
7	import { syncPortForwards } from "./network";
8	import { billingSweep } from "./billing";
9	import { randomBytes } from "node:crypto";
10	import type { Job, Server } from "@prisma/client";
11	
12	const POLL_MS = 3000;
13	const MAX_ATTEMPTS = 3;
14	
15	function generatePassword(): string {
16	  // URL-safe, no ambiguous chars, 16 chars
17	  return randomBytes(24).toString("base64url").replace(/[-_]/g, "x").slice(0, 16);
18	}
19	
20	async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any }> {
21	  const server = await db.server.findUnique({
22	    where: { id: job.serverId! },
23	    include: { plan: true, osTemplate: true, node: true },
24	  });
25	  if (!server) throw new Error(`Server ${job.serverId} not found`);
26	  return server as any;
27	}
28	
29	/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
30	async function nodeFor(server: any) {
31	  const n =
32	    server.node ??
33	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
34	    (await db.node.findFirst({ where: { enabled: true } }));
35	  if (!n) {
36	    // No Node rows yet — use the env-configured primary via the global client.
37	    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
38	  }
39	  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
40	}
