42	/** YAML-safe indent of a multi-line script under a `content: |` block. */
43	function indentBlock(text: string, spaces: number): string {
44	  const pad = " ".repeat(spaces);
45	  return text.split("\n").map((l) => pad + l).join("\n");
46	}
47	
48	/**
49	 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
50	 * plus any control-panel/app install script and selected add-ons. Long installs
51	 * run in the background so the VM reports ready promptly.
52	 */
53	function buildCloudInit(server: any): string {
54	  const addons = (server.addons ?? {}) as { malwareScanner?: boolean; dailyBackup?: boolean; docker?: boolean };
55	  const setup: string[] = [];
56	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
57	  if (addons.malwareScanner)
58	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
59	  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);
60	
61	  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
62	  return `#cloud-config
63	package_update: true
64	packages:
65	  - qemu-guest-agent
66	ssh_pwauth: true
67	disable_root: false
68	write_files:
69	  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
70	    permissions: "0644"
71	    content: |
72	      PermitRootLogin yes
73	      PasswordAuthentication yes
74	  - path: /root/nxeon-setup.sh
75	    permissions: "0755"
76	    content: |
77	${indentBlock(script, 6)}
78	runcmd:
79	  - systemctl enable --now qemu-guest-agent
80	  - systemctl restart ssh || systemctl restart sshd
81	  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
82	`;
83	}
84	
85	const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
86	const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";
87	
88	async function provision(job: Job) {
89	  const server = await loadServer(job);
90	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });
91	
92	  const { conn, row: nodeRow } = await nodeFor(server);
93	  const storage = server.plan.storageTier === "hdd"
94	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
95	    : nodeRow?.storageNvme ?? "vmdata";
96	
97	  const vmid = server.vmid ?? (await conn.nextVmid());
98	  const password = generatePassword();
99	
100	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
101	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
102	  if (server.wantsDedicatedIp && ovhConfigured()) {
103	    try {
104	      dedicated = await allocateDedicatedIp(server.id, vmid);
105	    } catch (e) {
106	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
107	    }
108	  }
109	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp()));
110	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort()));
111	
112	  await db.server.update({
113	    where: { id: server.id },
114	    data: { vmid, ipAddress: ip, sshPort, rootPassword: password },
115	  });
116	
117	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
118	  const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
119	    newid: vmid,
120	    name: server.hostname,
121	    full: 1,
122	    storage,
123	  });
124	  await conn.waitForTask(cloneUpid, 600_000);
125	
126	  // Per-server cloud-init snippet (base + panel/app install + add-ons)
127	  const snippet = buildCloudInit(server);
128	  await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8").catch((e) =>
129	    console.error("[worker] snippet write failed", e)
130	  );
131	
132	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
133	  const sshkeys = keys.length
134	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
135	    : undefined;
136	  const cfg: Record<string, any> = {
137	    cores: server.plan.cpuCores,
138	    memory: server.plan.ramMB,
139	    ciuser: "root",
140	    cipassword: password,
141	    sshkeys,
142	    nameserver: "1.1.1.1 8.8.8.8",
143	    onboot: 1,
144	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
145	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
146	  };
147	  if (dedicated) {
148	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
149	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
150	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
151	  } else {
152	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp()}`;
153	  }
154	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
155	
156	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
157	    disk: "scsi0",
158	    size: `${server.plan.diskGB}G`,
159	  });
160	
161	  if (!dedicated) await syncPortForwards();
162	
163	  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
164	  await conn.waitForTask(startUpid);
165	
166	  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
167	  const isImage = server.osTemplate.category !== "PLAIN_OS";
168	  const sshLine = dedicated
169	    ? `ssh root@${dedicated.address}`
170	    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;
171	  await notify(
172	    server.userId,
173	    `Server ${server.hostname} is ready`,
174	    isImage ? `${server.osTemplate.name} is installing in the background (a few minutes). ${sshLine}` : sshLine,
175	    `/dashboard/servers/${server.id}`
176	  );
177	}
178	
179	async function powerAction(job: Job, action: "start" | "stop" | "reboot") {
180	  const server = await loadServer(job);
181	  const { conn } = await nodeFor(server);
182	  const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/${action}`, {});
183	  await conn.waitForTask(upid);
184	  await db.server.update({
185	    where: { id: server.id },
186	    data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
187	  });
188	}
189	
190	async function destroyVm(conn: any, vmid: number) {
191	  // Stop first (ignore failure if already stopped), then destroy
192	  try {
193	    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
194	    await conn.waitForTask(stopUpid);
195	  } catch {
196	    /* already stopped or does not exist */
197	  }
198	  const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${vmid}`, {
199	    "destroy-unreferenced-disks": 1,
200	    purge: 1,
201	  });
202	  await conn.waitForTask(delUpid, 600_000);
203	}
204	
205	async function remove(job: Job) {
206	  const server = await loadServer(job);
207	  const { conn } = await nodeFor(server);
208	  if (server.vmid) {
209	    try {
210	      await destroyVm(conn, server.vmid);
211	    } catch (e: any) {
212	      // VM may never have been created; only swallow "does not exist"
213	      if (!String(e?.body ?? e?.message).includes("does not exist")) throw e;
214	    }
215	    // Best-effort: remove the per-server cloud-init snippet
216	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
217	  }
218	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC)
219	  await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
220	  await db.server.delete({ where: { id: server.id } });
221	  await syncPortForwards();
222	}
223	
224	async function reinstall(job: Job) {
225	  const server = await loadServer(job);
226	  const { conn } = await nodeFor(server);
227	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
228	  if (server.vmid) await destroyVm(conn, server.vmid);
229	  await provision(job);
230	}
231	
232	async function suspend(job: Job, unsuspend: boolean) {
233	  const server = await loadServer(job);
234	  const { conn } = await nodeFor(server);
235	  if (unsuspend) {
236	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null } });
237	    await syncPortForwards();
238	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
239	    await conn.waitForTask(upid);
240	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
241	  } else {
242	    try {
243	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
244	      await conn.waitForTask(upid);
245	    } catch { /* may already be stopped */ }
246	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
247	    await syncPortForwards();
248	  }
249	}
250	
251	async function notify(userId: string, title: string, body?: string, href?: string) {
252	  try {
253	    await db.notification.create({ data: { userId, title, body, href } });
254	  } catch (e) {
255	    console.error("[worker] notify failed", e);
256	  }
257	}
258	
259	async function resize(job: Job) {
260	  const server = await loadServer(job);
261	  const payload = (job.payload ?? {}) as { planId?: string };
262	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
263	  if (!newPlan) throw new Error("resize: target plan not found");
264	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
265	
266	  const { conn } = await nodeFor(server);
267	  const wasRunning = server.status === "RUNNING";
268	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
269	    cores: newPlan.cpuCores,
270	    memory: newPlan.ramMB,
271	  });
272	  if (newPlan.diskGB > server.plan.diskGB) {
273	    await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
274	      disk: "scsi0",
275	      size: `${newPlan.diskGB}G`,
276	    });
277	  }
278	  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
279	  // CPU/RAM changes need a power cycle to apply
280	  if (wasRunning) {
281	    try {
282	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
