296	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
297	  const server = await loadServer(job);
298	  const payload = (job.payload ?? {}) as { name?: string };
299	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
300	  if (!name) throw new Error("snapshot: invalid name");
301	  const { conn } = await nodeFor(server);
302	  let upid: string;
303	  if (op === "create") {
304	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
305	  } else if (op === "delete") {
306	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
307	  } else {
308	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
309	  }
310	  await conn.waitForTask(upid, 600_000);
311	  if (op === "rollback") {
312	    // rollback leaves the VM stopped; bring it back if the server should be running
313	    const current = await db.server.findUnique({ where: { id: server.id } });
314	    if (current?.status === "RUNNING") {
315	      try {
316	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
317	        await conn.waitForTask(startUpid);
318	      } catch { /* may already be running */ }
319	    }
320	  }
321	}
