323	async function passwordReset(job: Job) {
324	  const server = await loadServer(job);
325	  if (!server.vmid) throw new Error("password reset: server has no VM yet");
326	  const { conn } = await nodeFor(server);
327	  const password = generatePassword();
328	
329	  // Preferred path: set it live via the qemu-guest-agent (no reboot needed).
330	  let applied = false;
331	  try {
332	    const upid = await conn.post(
333	      `/nodes/${conn.node}/qemu/${server.vmid}/agent/set-user-password`,
334	      { username: "root", password }
335	    );
336	    if (typeof upid === "string" && upid.startsWith("UPID")) await conn.waitForTask(upid);
337	    applied = true;
338	  } catch (e) {
339	    console.error("[worker] agent set-user-password failed, falling back to cloud-init", e);
340	  }
341	
342	  // Fallback: rewrite cloud-init password and reboot so it reapplies.
343	  if (!applied) {
344	    await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { cipassword: password });
345	    if (server.status === "RUNNING") {
346	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/reboot`, {});
347	      await conn.waitForTask(upid);
348	    }
349	  }
350	
351	  await db.server.update({ where: { id: server.id }, data: { rootPassword: password } });
352	  await notify(
353	    server.userId,
354	    `Root password reset for ${server.hostname}`,
355	    "Your new root password is available on the server's Overview tab.",
356	    `/dashboard/servers/${server.id}`
357	  );
358	}
