362	  const { conn } = await nodeFor(server);
363	  const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
364	    vmid: server.vmid,
365	    storage: "backup",
366	    mode: "snapshot",
367	    compress: "zstd",
368	  });
