374	const handlers: Record<string, (job: Job) => Promise<void>> = {
375	  PROVISION: provision,
376	  START: (j) => powerAction(j, "start"),
377	  STOP: (j) => powerAction(j, "stop"),
378	  REBOOT: (j) => powerAction(j, "reboot"),
379	  DELETE: remove,
380	  REINSTALL: reinstall,
381	  SUSPEND: (j) => suspend(j, false),
382	  UNSUSPEND: (j) => suspend(j, true),
383	  RESIZE: resize,
384	  SNAPSHOT_CREATE: (j) => snapshotOp(j, "create"),
385	  SNAPSHOT_DELETE: (j) => snapshotOp(j, "delete"),
386	  SNAPSHOT_ROLLBACK: (j) => snapshotOp(j, "rollback"),
387	  BACKUP_CREATE: backupCreate,
388	  PASSWORD_RESET: passwordReset,
389	  SYNC_FORWARDS: async () => syncPortForwards(),
390	};
