392	async function runJob(job: Job) {
393	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
394	  await db.job.update({
395	    where: { id: job.id },
396	    data: { status: "RUNNING", attempts: { increment: 1 } },
397	  });
398	  try {
399	    await handlers[job.type](job);
400	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
401	    console.log(`[worker] job ${job.id} DONE`);
402	  } catch (e: any) {
403	    const error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`.slice(0, 2000);
404	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
405	    const current = await db.job.findUnique({ where: { id: job.id } });
406	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
407	    await db.job.update({
408	      where: { id: job.id },
409	      data: { status: retriable ? "QUEUED" : "FAILED", error },
410	    });
411	    if (!retriable && job.serverId) {
412	      const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
413	      if (stillExists) {
414	        await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
415	      }
416	    }
417	  }
418	}
419	
420	/**
421	 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
422	 * killed worker leaves a job RUNNING forever, which permanently blocks the
423	 * server's "one in-flight job" guard and strands it in a transitional state.
424	 */
425	async function reapStuckJobs() {
426	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
427	  for (const job of stuck) {
428	    const retriable = job.attempts < MAX_ATTEMPTS;
429	    await db.job.update({
430	      where: { id: job.id },
431	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
432	    });
433	    if (!retriable && job.serverId) {
434	      const s = await db.server.findUnique({ where: { id: job.serverId } });
435	      if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
436	        await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
437	      }
438	    }
439	    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${retriable ? "QUEUED" : "FAILED"}`);
440	  }
441	}
442	
443	async function main() {
444	  console.log("[worker] Nxeon provisioning worker starting");
445	  await reapStuckJobs();
446	  await syncPortForwards();
447	  console.log("[worker] port forwards synced");
448	
449	  let lastSweep = 0;
450	  let lastIpSync = 0;
451	  for (;;) {
452	    if (Date.now() - lastSweep > 10 * 60_000) {
453	      lastSweep = Date.now();
454	      try {
455	        await billingSweep();
456	      } catch (e) {
457	        console.error("[billing] sweep error", e);
458	      }
459	    }
460	    // Pull newly-delivered OVH IPs into the pool every 5 min
461	    if (ovhConfigured() && Date.now() - lastIpSync > 5 * 60_000) {
462	      lastIpSync = Date.now();
463	      try {
464	        const r = await syncDedicatedIpPool();
465	        if (r.imported > 0) console.log(`[worker] dedicated IP pool: imported ${r.imported}, total ${r.total}`);
466	      } catch (e) {
467	        console.error("[worker] IP pool sync error", e);
468	      }
469	    }
470	    try {
471	      const job = await db.job.findFirst({
472	        where: { status: "QUEUED" },
473	        orderBy: { createdAt: "asc" },
474	      });
475	      if (job) {
476	        await runJob(job);
477	      } else {
478	        await new Promise((r) => setTimeout(r, POLL_MS));
479	      }
480	    } catch (e) {
481	      console.error("[worker] loop error", e);
482	      await new Promise((r) => setTimeout(r, POLL_MS));
483	    }
484	  }
485	}
486	
487	main();
