18	 * Validated (<= 40 chars, control chars stripped) and ownership-checked.
19	 */
20	export async function renameServer(
21	  serverId: string,
22	  label: string
23	): Promise<{ error?: string; label?: string | null }> {
24	  const { user } = await ownedServer(serverId);
25	
26	  // Strip ASCII control characters, collapse whitespace, then trim.
27	  const clean = (label ?? "")
28	    .replace(/[\x00-\x1f\x7f]/g, "")
29	    .replace(/\s+/g, " ")
30	    .trim();
31	  if (clean.length > 40) return { error: "Name must be 40 characters or fewer." };
32	  const value = clean.length === 0 ? null : clean;
33	
34	  await db.server.update({ where: { id: serverId }, data: { label: value } });
35	  await db.auditLog.create({
36	    data: {
37	      userId: user.id,
38	      action: "server.rename",
39	      detail: `${serverId} -> ${value ?? "(cleared)"}`,
40	    },
41	  });
42	  revalidatePath(`/dashboard/servers/${serverId}`);
43	  return { label: value };
44	}
