"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { listBackups } from "./proxmox";
import { GAME_FAMILIES, type GameFamily } from "./games";

/**
 * Server-ops actions: game-server auto-update toggle + "update now", and
 * self-service backup restore. Every action re-verifies ownership.
 */

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

/** Is this server's image a managed game family? */
function isGameServer(server: { osTemplate: { family: string } }): boolean {
  return GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
}

/** Reject if another job is already queued/running on this server. */
async function ensureIdle(serverId: string): Promise<{ error?: string }> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) return { error: "Another operation is already in progress on this server." };
  return {};
}

// ---------- Game-server auto-update ----------

/**
 * Toggle `Server.autoUpdate` for a game server. Read-only for non-game images
 * (returns an error). The periodic worker sweep uses this flag.
 */
export async function toggleAutoUpdate(
  serverId: string,
  enabled: boolean
): Promise<{ error?: string; autoUpdate?: boolean }> {
  const { user, server } = await ownedServer(serverId);
  if (!isGameServer(server)) return { error: "Auto-update is only available for game servers." };

  await db.server.update({ where: { id: server.id }, data: { autoUpdate: enabled } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.auto_update_toggle",
      detail: `${serverId} -> ${enabled ? "on" : "off"}`,
    },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { autoUpdate: enabled };
}

/**
 * Enqueue a one-off GAME_UPDATE job. The worker SSHes the per-family update
 * command over the private network, so the VM must be running.
 */
export async function triggerGameUpdate(serverId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  if (!isGameServer(server)) return { error: "Updates are only available for game servers." };
  if (server.status !== "RUNNING") {
    return { error: "Server must be running to apply a game update." };
  }
  if (!server.ipAddress || !server.rootPassword) {
    return { error: "Server is still provisioning — try again shortly." };
  }
  const idle = await ensureIdle(serverId);
  if (idle.error) return idle;

  await db.job.create({ data: { type: "GAME_UPDATE", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "server.game_update", detail: serverId },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- Self-service backup restore ----------

export type ServerBackup = { volid: string; ctime?: number; size?: number };

/**
 * List the vzdump backups on the `backup` storage that belong to this server's
 * VMID. Read-only Proxmox call, ownership-checked.
 */
export async function listServerBackups(
  serverId: string
): Promise<{ error?: string; backups?: ServerBackup[] }> {
  const { server } = await ownedServer(serverId);
  if (!server.vmid) return { backups: [] };
  try {
    const backups = (await listBackups(server.vmid)) as ServerBackup[];
    backups.sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
    return { backups };
  } catch {
    return { error: "Could not reach the hypervisor — try again in a moment." };
  }
}

/**
 * Enqueue a BACKUP_RESTORE job for the selected vzdump archive. This OVERWRITES
 * the server's current disk. The volid is validated against the server's own
 * backups so a customer can only restore their own VM's archives.
 */
export async function requestRestore(
  serverId: string,
  volid: string
): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  if (!server.vmid) return { error: "Server has no VM yet." };
  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to restore a backup." };
  }

  // Validate the archive actually belongs to this server's VMID (prevents
  // restoring another customer's backup by guessing a volid).
  let owned: ServerBackup[];
  try {
    owned = (await listBackups(server.vmid)) as ServerBackup[];
  } catch {
    return { error: "Could not verify the backup — the hypervisor is briefly unavailable." };
  }
  if (!owned.some((b) => b.volid === volid)) {
    return { error: "That backup was not found for this server." };
  }

  const idle = await ensureIdle(serverId);
  if (idle.error) return idle;

  await db.job.create({ data: { type: "BACKUP_RESTORE", serverId, payload: { volid } } });
  await db.auditLog.create({
    data: { userId: user.id, action: "server.backup_restore", detail: `${serverId} ${volid}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

import { db } from "../lib/db";
import { GAME_FAMILIES, type GameFamily } from "../lib/games";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import type { Job } from "@prisma/client";

const execFileP = promisify(execFile);

/**
 * Game-server auto-update handlers.
 *
 * `gameUpdate` runs a best-effort, per-family update command over SSH against
 * the server's private IP (the worker can reach vmbr1). `gameUpdateSweep` finds
 * RUNNING game servers with `autoUpdate=true` and enqueues GAME_UPDATE jobs for
 * them — safe to call periodically (it de-dupes on in-flight jobs).
 *
 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire these
 * in there (`GAME_UPDATE: gameUpdate`) and call `gameUpdateSweep()` on a timer.
 */

/** Steam dedicated-server app IDs for steamcmd-based families. */
const STEAM_APPID: Partial<Record<GameFamily, string>> = {
  valheim: "896660",
  rust: "258550",
  palworld: "2394010",
  cs2: "730",
};

/** systemd service name candidates per family (first that exists wins). */
const SERVICE_HINT: Record<GameFamily, string> = {
  minecraft: "minecraft",
  valheim: "valheim",
  rust: "rust",
  palworld: "palworld",
  cs2: "cs2",
  terraria: "terraria",
};

/**
 * Build a best-effort remote update command. For steamcmd-based games we run an
 * anonymous `app_update ... validate` if steamcmd is present, then (always)
 * restart the matching systemd service. Everything is tolerant (`|| true`) so a
 * missing tool/service never fails the whole job for an otherwise-healthy VM.
 */
function updateCommand(family: GameFamily): string {
  const appId = STEAM_APPID[family];
  const svc = SERVICE_HINT[family];
  const steam = appId
    ? `if command -v steamcmd >/dev/null 2>&1; then steamcmd +login anonymous +app_update ${appId} validate +quit || true; fi; `
    : "";
  // Restart the named service, then a "<family>-server" variant, then any unit
  // whose name contains the family; never hard-fail.
  const restart =
    `systemctl restart ${svc} 2>/dev/null || ` +
    `systemctl restart ${svc}-server 2>/dev/null || ` +
    `svc=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${family} | head -1 | awk '{print $1}'); ` +
    `if [ -n "$svc" ]; then systemctl restart "$svc" || true; fi`;
  return `set -e; ${steam}${restart}; true`;
}

async function loadGameServer(serverId: string) {
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true },
  });
  if (!server) throw new Error(`Server ${serverId} not found`);
  return server;
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-update] notify failed", e);
  }
}

/** Run the per-family update command over SSH (sshpass + private IP). */
export async function gameUpdate(job: Job): Promise<void> {
  const server = await loadGameServer(job.serverId!);
  const family = server.osTemplate.family as GameFamily;
  if (!GAME_FAMILIES.includes(family)) {
    throw new Error(`game update: ${server.hostname} is not a game server`);
  }
  if (server.status !== "RUNNING") throw new Error("game update: server is not running");
  if (!server.ipAddress || !server.rootPassword) {
    throw new Error("game update: server has no IP/password yet");
  }

  const remote = updateCommand(family);
  await execFileP(
    "sshpass",
    [
      "-p",
      server.rootPassword,
      "ssh",
      "-o",
      "StrictHostKeyChecking=no",
      "-o",
      "UserKnownHostsFile=/dev/null",
      "-o",
      "ConnectTimeout=15",
      `root@${server.ipAddress}`,
      remote,
    ],
    { timeout: 600_000, maxBuffer: 4 * 1024 * 1024 }
  );

  await notify(
    server.userId,
    `${server.osTemplate.name} updated on ${server.hostname}`,
    "The latest server update was applied and the service was restarted.",
    `/dashboard/servers/${server.id}`
  );
}

/**
 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
 * auto-update and has no job already in flight. Idempotent / safe to call on a
 * timer. Returns nothing; logs a summary.
 */
export async function gameUpdateSweep(): Promise<void> {
  const candidates = await db.server.findMany({
    where: {
      status: "RUNNING",
      autoUpdate: true,
      osTemplate: { family: { in: [...GAME_FAMILIES] } },
    },
    select: { id: true, hostname: true },
  });
  if (candidates.length === 0) return;

  let enqueued = 0;
  for (const s of candidates) {
    const inflight = await db.job.count({
      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (inflight > 0) continue;
    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
    enqueued++;
  }
  if (enqueued > 0) console.log(`[game-update] sweep enqueued ${enqueued} update job(s)`);
}

import { db } from "../lib/db";
import { pve, node as envNode, waitForTask, nextVmid, pveFor, vmStatus } from "../lib/proxmox";
import type { Job } from "@prisma/client";

/**
 * Self-service backup restore handler.
 *
 * Restores a selected vzdump archive back onto the server's existing VM via the
 * Proxmox API: stop -> restore (force overwrite) -> start. Ownership and archive
 * validation are enforced at enqueue time (`lib/actions-server-ops.ts`), so this
 * handler trusts the `volid` in the job payload.
 *
 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire this in
 * there as `BACKUP_RESTORE: backupRestore`.
 */

async function loadServer(serverId: string) {
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { node: true },
  });
  if (!server) throw new Error(`Server ${serverId} not found`);
  return server;
}

/** Resolve a Proxmox client for the server's node (mirrors worker/index.ts). */
async function nodeFor(server: any) {
  const n =
    server.node ??
    (await db.node.findFirst({ where: { isPrimary: true } })) ??
    (await db.node.findFirst({ where: { enabled: true } }));
  if (!n) {
    return {
      get: pve.get,
      post: pve.post,
      put: pve.put,
      del: pve.del,
      node: envNode,
      waitForTask,
      nextVmid,
      vmStatus: (v: number) => pve.get(`/nodes/${envNode}/qemu/${v}/status/current`),
    } as any;
  }
  return pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret });
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[restore] notify failed", e);
  }
}

export async function backupRestore(job: Job): Promise<void> {
  const server = await loadServer(job.serverId!);
  if (!server.vmid) throw new Error("restore: server has no VM");

  const payload = (job.payload ?? {}) as { volid?: string };
  const volid = payload.volid;
  if (!volid) throw new Error("restore: missing volid");

  const conn = await nodeFor(server);
  const vmid = server.vmid;
  const wasRunning = server.status === "RUNNING";

  // 1) Stop the VM so the disk can be overwritten (ignore "already stopped").
  try {
    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
    await conn.waitForTask(stopUpid);
  } catch {
    /* already stopped / not running */
  }
  await db.server.update({ where: { id: server.id }, data: { status: "STOPPED" } });

  // 2) Restore the archive over the existing VMID (force overwrite). Storage is
  //    left to the archive's recorded config so disks land where they were.
  const restoreUpid = await conn.post(`/nodes/${conn.node}/qemu`, {
    vmid,
    archive: volid,
    force: 1,
  });
  await conn.waitForTask(restoreUpid, 3_600_000);

  // 3) Bring the VM back up if it was running before the restore.
  if (wasRunning) {
    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
    await conn.waitForTask(startUpid);
    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
  }

  await notify(
    server.userId,
    `Backup restored on ${server.hostname}`,
    "Your server was restored from the selected backup. Any changes made after that backup are gone.",
    `/dashboard/servers/${server.id}`
  );
}

