"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { toggleAutoUpdate, triggerGameUpdate } from "@/lib/actions-server-ops";

/**
 * Game-server auto-update controls: a toggle for `Server.autoUpdate` plus an
 * "Update now" button that enqueues a one-off GAME_UPDATE job.
 */
export function GameAutoUpdate({
  serverId,
  gameName,
  autoUpdate,
  canUpdate,
  busy,
}: {
  serverId: string;
  gameName: string;
  autoUpdate: boolean;
  /** true when the VM is RUNNING (required for the SSH update) */
  canUpdate: boolean;
  /** true when another job is in flight */
  busy: boolean;
}) {
  const router = useRouter();
  const [enabled, setEnabled] = useState(autoUpdate);
  const [error, setError] = useState<string | null>(null);
  const [savingToggle, startToggle] = useTransition();
  const [updating, startUpdate] = useTransition();

  function flip() {
    const next = !enabled;
    setEnabled(next); // optimistic
    startToggle(async () => {
      setError(null);
      const res = await toggleAutoUpdate(serverId, next);
      if (res?.error) {
        setEnabled(!next); // revert
        setError(res.error);
      }
    });
  }

  function updateNow() {
    startUpdate(async () => {
      setError(null);
      const res = await triggerGameUpdate(serverId);
      if (res?.error) setError(res.error);
      else router.refresh();
    });
  }

  return (
    <div className="card">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <h2 className="font-semibold">Game updates</h2>
          <p className="mt-1 max-w-md text-sm text-slate-400">
            Keep your {gameName} server current. Updates run the game&apos;s update command over SSH
            and restart the service — expect a short interruption while it applies.
          </p>
        </div>
        <button
          className="btn-primary"
          disabled={updating || busy || !canUpdate}
          onClick={updateNow}
          title={!canUpdate ? "Server must be running" : undefined}
        >
          {updating ? "Queueing…" : "Update now"}
        </button>
      </div>

      <div className="divider" />

      <label className="flex cursor-pointer items-center justify-between gap-4">
        <span className="text-sm">
          <span className="font-medium">Automatic updates</span>
          <span className="mt-0.5 block text-xs text-slate-500">
            When on, we periodically update this server to the latest version in the background.
          </span>
        </span>
        <button
          type="button"
          role="switch"
          aria-checked={enabled}
          disabled={savingToggle}
          onClick={flip}
          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
            enabled ? "bg-brand-500" : "bg-white/15"
          } ${savingToggle ? "opacity-60" : ""}`}
        >
          <span
            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
              enabled ? "translate-x-5" : "translate-x-0.5"
            }`}
          />
        </button>
      </label>

      {error && <p className="mt-3 text-sm text-red-400">{error}</p>}
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { requestRestore } from "@/lib/actions-server-ops";
import { fmtBytes } from "@/components/ui/primitives";

type Backup = { volid: string; ctime?: number; size?: number };

function fmtWhen(ctime?: number): string {
  if (!ctime) return "—";
  return new Date(ctime * 1000).toISOString().slice(0, 16).replace("T", " ");
}

/**
 * Self-service restore: lists the server's vzdump backups and lets the owner
 * restore one, enqueuing a BACKUP_RESTORE job. Restore OVERWRITES the current
 * disk, so it is guarded by a typed/explicit confirm.
 */
export function BackupRestore({
  serverId,
  backups,
  unavailable,
  disabled,
}: {
  serverId: string;
  backups: Backup[];
  unavailable?: boolean;
  disabled?: boolean;
}) {
  const router = useRouter();
  const [error, setError] = useState<string | null>(null);
  const [pendingVolid, setPendingVolid] = useState<string | null>(null);
  const [isPending, start] = useTransition();

  function restore(b: Backup) {
    const name = b.volid.split("/").pop() ?? b.volid;
    const ok = window.confirm(
      `Restore this server from backup:\n\n${name}\n(${fmtWhen(b.ctime)})\n\n` +
        "This OVERWRITES your server's current disk — every change made since this " +
        "backup will be permanently lost. The server is stopped, restored, then " +
        "started again.\n\nContinue?"
    );
    if (!ok) return;
    setPendingVolid(b.volid);
    start(async () => {
      setError(null);
      const res = await requestRestore(serverId, b.volid);
      setPendingVolid(null);
      if (res?.error) setError(res.error);
      else router.refresh();
    });
  }

  return (
    <div className="card p-0">
      <div className="flex items-center justify-between px-4 pt-4">
        <p className="section-label">Restore from backup</p>
      </div>

      {error && <p className="px-4 pt-2 text-sm text-red-400">{error}</p>}

      {unavailable && backups.length === 0 ? (
        <p className="px-4 py-6 text-sm text-amber-300">
          Could not load backups — the hypervisor is briefly unavailable. Try again in a moment.
        </p>
      ) : backups.length === 0 ? (
        <p className="px-4 py-6 text-sm text-slate-400">
          No backups to restore yet. Create a backup above first — then you can roll the whole server
          back to it here.
        </p>
      ) : (
        <table className="table-shell mt-2">
          <thead>
            <tr>
              <th>Backup</th>
              <th>Created</th>
              <th className="text-right">Size</th>
              <th className="text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {backups.map((b) => {
              const thisPending = isPending && pendingVolid === b.volid;
              return (
                <tr key={b.volid}>
                  <td className="font-mono text-xs">{b.volid.split("/").pop()}</td>
                  <td className="text-slate-400">{fmtWhen(b.ctime)}</td>
                  <td className="text-right text-slate-400">{fmtBytes(b.size ?? 0)}</td>
                  <td className="text-right">
                    <button
                      className="btn-danger px-3 py-1 text-xs"
                      disabled={disabled || isPending}
                      onClick={() => restore(b)}
                    >
                      {thisPending ? "Queueing…" : "Restore"}
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}

      <p className="px-4 py-4 text-xs text-slate-500">
        Restoring overwrites the live disk with the backup&apos;s contents. Take a fresh backup first
        if you might want today&apos;s data back.
      </p>
    </div>
  );
}

